SELECT id, symbol, status, started_at, last_evidence_at, anchor_entry_price, best_entry_price, evidence_count, buy_count, watch_count, neutral_count, bearish_count, opportunity_health, execution_source, decision_code, latest_signal_id, executed_at, updated_at FROM crypto_ai.execution_opportunity WHERE (symbol='XRPUSDT' AND started_at BETWEEN '2026-10-12 00:30:00' AND '2026-10-12 02:35:04') OR (symbol='SHIBUSDT' AND started_at BETWEEN '2026-10-12 04:30:00' AND '2026-10-12 06:36:04') ORDER BY symbol, started_at LIMIT 80;
SELECT id, signal_id, execution_reason, LEFT(execution_message,2000) AS msg, executed_at FROM crypto_ai.wallet_trade WHERE side='BUY' AND signal_id IN (165412,165415) LIMIT 5;